-- The Storm Peaks: combat SmartAI for 58 creatures that cast no spell here and had no AI.
-- Rows from 5.4.8 (Legends of Azeroth), taken only where every event, action and target type is numbered the same in this core,
-- every spell is in the client data and 3.3.5 casts at least half of the same spells. Quest, summon and waypoint scripts are not included.
UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `entry` IN (29323,29350,29369,29370,29374,29376,29380,29382,29390,29404,29407,29409,29411,29412,29413,29426,29461,29469,29504,29518,29553,29554,29569,29570,29586,29623,29624,29652,29755,29792,29793,29794,29808,29843,29844,29875,29910,29942,29960,29973,29980,29981,29996,30147,30160,30167,30184,30292,30300,30341,30353,30376,30387,30445,30447,30448,30450,31797) AND `ScriptName` = '';
